import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String string = scanner.nextLine();

        while (string.substring(1, string.length() - 1).contains("dot")) {
            int indexDot = string.substring(1).indexOf("dot") + 1;
            string = string.substring(0, indexDot) + "." + string.substring(indexDot + 3);
        }

        int indexAt = string.substring(1).indexOf("at") + 1;
        string = string.substring(0, indexAt) + "@" + string.substring(indexAt + 2);
        System.out.println(string);
        scanner.close();
    }
}
